341:/// Pins each Scrollable to its semantic story end. ChatAnimatedList is
342:/// reversed (newest at offset zero); regular lists and the app overlay use
343:/// their maximum extent. Treating every list alike hid the assistant answer
344:/// behind the composer in the original store captures.
345:void _jumpScrollablesToStoryEnd(WidgetTester tester) {
346:  for (final element in find.byType(Scrollable).evaluate()) {
347:    final state = (element as StatefulElement).state as ScrollableState;
348:    // Exact-type ScrollView never matches the transcript's
349:    // CustomScrollView (nor a ListView): both are subclasses, so the old
350:    // check silently pinned the "reversed" chat to its OLDEST offset.
351:    final custom = element.findAncestorWidgetOfExactType<CustomScrollView>();
352:    final list = element.findAncestorWidgetOfExactType<ListView>();
353:    final reverse = custom?.reverse ?? list?.reverse ?? false;
354:    final extent = reverse
355:        ? state.position.minScrollExtent
356:        : state.position.maxScrollExtent;
357:    state.position.jumpTo(extent);
358:  }
359:}
