29:String? pasteboardPlatform(String? platform) {
30:  if (platform != null) return platform;
31:  if (Platform.isMacOS) return 'macos';
32:  if (Platform.isLinux) return 'linux';
33:  if (Platform.isWindows) return 'windows';
